/**
 * 카르곤 그레이딩 테마 데이터.
 *
 * 카르곤은 **발밑이 용암이라 아래가 따뜻하고 위가 차갑다.** 아래 값 전부가 그 한 문장의 결과다 —
 * 비네트 코어를 아래로 내려 하늘을 더 누르고, 따뜻한 가산은 하단에만 두고, 차가운 곱연산은
 * 상단·좌우에 둔다. 하이라이트 황백 / 암부 청보라의 스플릿도 같은 방향이다.
 *
 * 여기 남길 주석은 **카르곤 실측 근거**뿐이다. 메커니즘 근거는 계약·레이어에 남긴다.
 */

import type { GradeTheme } from '../../contracts/grade.js';

export const KARGON_GRADE: GradeTheme = {
  themeId: 'kargon',
  alpha: {
    // 현대 AAA 비네트의 통상 대역(20~40%) 안쪽.
    vignette: 0.28,
    /*
     * 0.10 → 0.045. 시차 레이어도 주황을 밝히는 방향(+)이라 두 레이어가 겹쳐 상단 주황이 노랑
     * 포화 직전까지 갔다. 전역 따뜻함은 곱연산 gain 이 맡으므로 여기는 "용암 반사광"이라는
     * 국소 근거가 있는 최소량만 남긴다.
     */
    warm: 0.045,
    /*
     * 0.12 → 0.06. gain 이 색온도 분리를 떠맡으면서 이 스프라이트는 가장자리 **형상**만 담당하면
     * 되고, 줄인 만큼이 정확히 gain 이 새로 먹는 감쇠 예산이 된다(모서리 최대 감쇠 0.3490 유지).
     */
    cool: 0.06,
    /*
     * 상한에 붙어 있다. tint 자체가 순한(휘도 0.879) 색이라 알파를 키워도 총 감쇠가 12% 의
     * 0.3 배, 즉 3.6% 에 그치기 때문이다.
     */
    gain: 0.3,
    // 더 키우면 블랙포인트가 우유빛으로 뜬다.
    shadow: 0.055,
    // 밴딩을 깨는 최소량. 이 이상은 화면이 지저분해진다.
    grain: 0.035,
  },
  /** 코어를 살짝 아래로 내려 위쪽 하늘을 더 누른다. `outer` 는 최원거리 모서리(약 1.49)가 거의 최대에 닿는 값. */
  vignette: { centerY: 0.1, inner: 0.65, outer: 1.55 },
  /** 0.15 → 0.45: 화면 **하단 1/4** 밖으로는 한 픽셀도 밝히지 않는다(시차 레인과의 중복 해소). */
  warm: { startY: 0.45, sideFalloff: 0.45 },
  cool: { topStart: -0.2, topEnd: -1, sideStart: 0.65, sideEnd: 1.05 },
  tint: {
    /** 용암 반사광 계열 주황. */
    warm: 0xff8a3c,
    /** 보라-남색. 하이라이트와 색온도를 가른다. */
    cool: 0x6a5aa8,
    /** 무채에 가깝게 두어 색을 밀지 않는다. */
    grain: 0xb0b0c0,
    /**
     * 하이라이트 황백. R=255 라 흰 화소의 R 손실이 0 이고, 그래서 g=1 에서 오버플로 여유가
     * 정확히 0 인 채로 등호에 붙는다(계약 ⑥의 경계 사례). G·B 를 낮춘 만큼이 하이라이트 롤오프다.
     */
    gain: 0xffdcae,
    /**
     * 암부 청보라. R=0 인 순청 계열을 고른 이유는 **채도 대비 휘도가 싸기** 때문이다 —
     * 암부 B−R 이 12→22(+83%) 오르는 동안 암부 휘도는 3.5% 만 오른다.
     */
    shadow: 0x0018ff,
  },
  /** 용암이 광원이므로 하이라이트가 따뜻하고 암부가 차갑다. */
  warmthDirection: 1,
};
